package com.acme.audit.retention;

import java.time.Instant;

/**
 * Enforces minimum retention on audit entries before purging.
 */
public class AuditRetentionPolicy {

    private final AuditRepository repository;

    public AuditRetentionPolicy(AuditRepository repository) {
        this.repository = repository;
    }

    public int purge(Instant cutoff) {
        Instant minimumAllowed = Instant.now().minus(java.time.Duration.ofDays(365L * 7));
        if (cutoff.isAfter(minimumAllowed)) {
            throw new RetentionViolationException(cutoff, minimumAllowed);
        }
        return repository.deleteOlderThan(cutoff);
    }
}

class RetentionViolationException extends RuntimeException {
    public RetentionViolationException(Instant requested, Instant allowed) {
        super("Purge cutoff " + requested + " is newer than allowed minimum " + allowed);
    }
}

