/**
 * Raises an alert when failures from an IP exceed the threshold in the window.
 */
public class FailedLoginAlertService {

    private final LoginEventRepository events;
    private final AlertPublisher publisher;

    public FailedLoginAlertService(LoginEventRepository events, AlertPublisher publisher) {
        this.events = events;
        this.publisher = publisher;
    }

    public void evaluate(String ipAddress, int threshold, Duration window) {
        Instant since = Instant.now().minus(window);
        long failures = events.countFailures(ipAddress, since);
        if (failures >= threshold) {
            publisher.raise(new SecurityAlert("FAILED_LOGIN_BURST", ipAddress, failures, since, Instant.now()));
        }
    }
}

