package com.acme.audit.appendonly;

import java.time.Instant;
import javax.persistence.EntityManager;
import javax.persistence.EntityTransaction;

/**
 * Append-only writer for the audit log. Only insert operations are exposed.
 */
public class AppendOnlyAuditWriter {

    private final EntityManager em;

    public AppendOnlyAuditWriter(EntityManager em) {
        this.em = em;
    }

    public void append(String actorId, String action, String targetType, String targetId) {
        EntityTransaction tx = em.getTransaction();
        tx.begin();
        try {
            AuditLogEntry entry = new AuditLogEntry();
            entry.setActorId(actorId);
            entry.setAction(action);
            entry.setTargetType(targetType);
            entry.setTargetId(targetId);
            entry.setOccurredAt(Instant.now());
            em.persist(entry);
            tx.commit();
        } catch (RuntimeException e) {
            tx.rollback();
            throw e;
        }
    }
}

