/* compress_audit.c - compress older audit entries into daily summaries */
#include <stdio.h>
#include "audit_db.h"

int compress_audit(const char *cutoff_date) {
    db_cursor_t *cur = NULL;
    if (db_open_audit_before_cursor(&cur, cutoff_date) != DB_OK) return -1;

    int compressed = 0;
    summary_row_t row;
    while (db_summary_cursor_next(cur, &row) == DB_OK) {
        if (db_upsert_daily_summary(row.actor_id, row.action, row.day, row.count) != DB_OK) {
            db_close_cursor(cur);
            return -2;
        }
        compressed += row.count;
    }
    db_close_cursor(cur);
    if (db_delete_audit_before(cutoff_date) != DB_OK) return -3;
    return compressed;
}

