#include <stdio.h>
#include "audit_db.h"

int export_audit(const char *from_date, const char *to_date, const char *path) {
    FILE *out = fopen(path, "w");
    if (!out) return -1;
    db_cursor_t *cur = NULL;
    if (db_open_audit_between_cursor(&cur, from_date, to_date) != DB_OK) { fclose(out); return -2; }
    audit_row_t row;
    while (db_audit_cursor_next(cur, &row) == DB_OK) {
        fprintf(out, "%s,%s,%s,%s,%s\n", row.actor_id, row.action, row.target_type, row.target_id, row.occurred_at);
    }
    db_close_cursor(cur);
    fclose(out);
    return 0;
}
